async function exportSelection(key,ids){if(!ids.length)return toast('กรุณาเลือกรายการก่อน',true);if(selectionAdapters.has(key)){await selectionAdapters.get(key)(ids);await logActivity('ส่งออกตัวอย่างนำเข้าที่เลือก',[],{count:ids.length});return;}if(key.startsWith('registry:')||key.startsWith('expired:')){const records=registryVisibleRecords().filter(r=>ids.includes(r.id));download(await registryWorkbook(state,records,'registry',year),'ทะเบียนที่เลือก.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');}else if(key.startsWith('weekly:')){download(xlsxBlob(state,selectedReport(),year),'รายงานที่เลือก.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');}else if(key.startsWith('catalog:')){const kind=key.split(':')[1];if(kind==='roadSections'){exportRoads(state.settings.roadSections.filter(r=>ids.includes(r.id)));return;}const copy={...state,[kind]:kind==='years'?state.years.filter(y=>ids.includes(String(y))):state[kind].filter(x=>ids.includes(x.id))};download(masterCSV(copy,kind),'ข้อมูลพื้นฐาน-'+kind+'.csv','text/csv;charset=utf-8');}else if(key==='quality'){download(JSON.stringify(qualityIssues(state,year,funding).filter(x=>ids.includes(qualityReviewKey(x))),null,2),'รายการตรวจที่เลือก.json','application/json');}else{let source=state;if(source.reports.some(r=>ids.includes(r.id)&&(r._unloaded||(r._storedSnapshot&&Object.keys(r.entries||{}).length&&!Object.keys(r.snapshots||{}).length)))){if(!navigator.onLine)throw Error('รายงานบางสัปดาห์ยังไม่ได้เก็บสำหรับออฟไลน์');source=await cloud.loadFullCloud();}download(JSON.stringify(fileDates(reportSelectionBackup(source,ids)),null,2),'รายงานที่เลือก.json','application/json');}await logActivity('ส่งออกรายการที่เลือก',[],{table:key,count:ids.length,ids});toast('ส่งออก '+ids.length+' รายการแล้ว');}
