function historyRows(){return historyPayload?.asset?assetHistoryRows(historyPayload,{routeNumber:historyRoute,controlSection:historyControl,year:historyYear==='all'?null:Number(historyYear),funding:historyFunding==='all'?null:historyFunding}):[];}
/** Render assetHistory from the current validated scope. @returns {string} HTML; does not save business records. */
