function weeklyArchiveStatus(){const r=report(),entries=Object.values(r.entries||{}),count=entries.filter(e=>e.confirmed).length;if(r.locked)return '<div class="notice success" role="status">เก็บรายงานเข้าคลังแล้ว · '+entries.length+' รายการ</div>';return `<div class="notice weekly-archive-status" role="status"><span><strong>ฉบับร่าง · ยืนยันแล้ว ${count} / ${entries.length} รายการ</strong><br>ยืนยันรายการแล้วต้องกดเก็บรายงานเพื่อบันทึกเข้าคลัง</span><button type="button" class="btn" data-action="lock">ตรวจข้อมูลก่อนเก็บรายงาน</button></div>`;}
