function archiveFilters(){return `<div class="period-bar unified-toolbar filter-bar-inline archive-period"><div class="period-control"><label class="field">กลุ่มงบ<select name="archiveFunding">${state.fundingSources.map(x=>`<option value="${x.id}" ${x.id===funding?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="field">ปีงบประมาณ<select name="archiveYear">${[...state.years].sort((a,b)=>b-a).map(y=>`<option value="${y}" ${y===year?'selected':''}>${y}</option>`).join('')}</select></label></div><div class="search-box search-field"><span class="search-icon">⌕</span><input id="archive-search" class="search" aria-label="ค้นหารายงาน" placeholder="ค้นหาสัปดาห์หรือช่วงวันที่ (กด / เพื่อค้นหา)" value="${esc(archiveQuery)}"><kbd class="search-shortcut">/</kbd>${archiveQuery?'<button class="search-clear" id="clear-archive" aria-label="ล้างคำค้น">×</button>':''}</div></div>`;}
function bindArchive(){const f=$('[name=archiveFunding]'),y=$('[name=archiveYear]');if(f){f.value=funding;f.onchange=async()=>{funding=f.value;archivePage=1;try{await ensureScope();}catch(e){toast(e.message,true);}render();};}if(y){y.value=String(year);y.onchange=async()=>{year=+y.value;archivePage=1;try{await ensureScope();}catch(e){toast(e.message,true);}render();};}$('#clear-archive')?.addEventListener('click',()=>{archiveQuery='';archivePage=1;render();$('#archive-search').focus();});$$('[data-archive-page]').forEach(b=>b.onclick=()=>{archivePage=+b.dataset.archivePage;render();});$$('[data-amend-info]').forEach(b=>b.onclick=()=>{const r=state.reports.find(r=>r.id===b.dataset.amendInfo);modal('แก้ไขรายงานแล้ว',`<p>แก้ไขล่าสุด ${esc(new Date(r.modifiedAt).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'}))}</p><p class="sub">แก้ไขแล้ว ${r.amendedVersion||1} ครั้ง</p>`);});}

