async function loadHistoryPage(page=1){if(!cloudMode){historyPageData=null;importHistoryPage=page;return;}const token=++historyRequest;const result=await cloud.loadHistoryPageCloud(page,auditQuery,auditFilter);if(!Array.isArray(result?.rows)||!Number.isInteger(result.page))throw Error('รูปแบบประวัติไม่ถูกต้อง กรุณาอัปเดตฐานข้อมูลและโหลดหน้าใหม่');if(token!==historyRequest)return;historyPageData=result;importHistoryPage=result.page;}
/** Render audit from the current validated scope. @returns {string} HTML; does not save business records. */
function audit(){const local=(state.importHistory||[]).flatMap(run=>(run.changes||[]).map((change,changeIndex)=>({run,change,changeIndex}))).filter(({run,change})=>historyRowMatches(run,change,auditQuery,auditFilter));const result=historyPageData||{rows:local.slice((importHistoryPage-1)*25,importHistoryPage*25),page:importHistoryPage,total:local.length,pages:Math.max(1,Math.ceil(local.length/25))};return header('ประวัติการเปลี่ยนแปลง','','<button class="btn" data-action="export-import-history">↓ ส่งออกประวัติ CSV</button>')+`<div class="card audit-panel"><div class="audit-toolbar"><input id="audit-search" class="search" aria-label="ค้นหาประวัติ" placeholder="ค้นหาชื่อไฟล์ การดำเนินการ หรือชื่อช่อง" value="${esc(auditQuery)}"><div class="audit-filter-tabs">${[['all','ทั้งหมด'],['updated','อัปเดต'],['new','เพิ่มใหม่'],['removed','เอาออก']].map(([k,l])=>`<button type="button" class="pill-toggle ${auditFilter===k?'active':''}" data-audit-filter="${k}">${l}</button>`).join('')}</div></div>${importHistoryHTML(result,result.page)}</div><div class="card"><h3>บันทึกกิจกรรมล่าสุด</h3>${(historyPageData?.audit||state.audit).slice(0,20).map(a=>`<div class="audit-item"><span>${esc(a.action)}</span><span class="sub">${new Date(a.at).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'})}</span></div>`).join('')||'<p>ยังไม่มีประวัติ</p>'}</div>`;}


