 const host=$('#registry-control-tools');if(host&&!$('#registry-column-settings')){const button=document.createElement('button');button.type='button';button.className='btn icon-action registry-column-settings';button.id='registry-column-settings';button.setAttribute('aria-label','เลือกคอลัมน์ที่แสดง');button.title='เลือกคอลัมน์ที่แสดง';button.innerHTML='<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="M9 4v16M15 4v16M3 10h18"/></svg><span class="registry-column-label">คอลัมน์</span>';button.onclick=()=>{const selected=registryHiddenColumns();modal('ตั้งค่าคอลัมน์ทะเบียนสัญญา',`<form id="registry-columns-form"><p class="hint">บันทึกเฉพาะอุปกรณ์นี้ ไม่เปลี่ยนข้อมูลและคอลัมน์ในไฟล์ส่งออก เลขสัญญาและปุ่มจัดการแสดงเสมอ</p><div class="column-choices">${registryColumnDefinitions.map(([key,label])=>`<label><input type="checkbox" name="column" value="${key}" ${selected.has(key)?'':'checked'} ${key==='contract'?'disabled':''}>${label}</label>`).join('')}</div>${buttons('นำไปใช้')}</form>`,f=>{const visible=new Set(f.getAll('column')),next=registryColumnDefinitions.filter(([key])=>key!=='contract'&&!visible.has(key)).map(([key])=>key);localStorage.setItem('pn-registry-hidden-columns-v1',JSON.stringify(next));render();});};host.prepend(button);}
