function bindWeeklyEntryInputs(){$$('[data-entry]').forEach(input=>{const reportId=selected,tr=input.closest('tr'),id=tr?.dataset.id,k=input.dataset.entry,key=reportId+'|'+id+'|'+k;if(!id)return;input.oninput=()=>{const rawVal=input.type==='checkbox'?input.checked:['plan','weekly','actual'].includes(k)?+input.value:input.value;editDrafts.set(key,{reportId,id,k,value:rawVal});const r=report(),e={...(r.entries?.[id]||{})};for(const field of ['plan','weekly','actual','payment','paymentDate','note']){const draft=editDrafts.get(reportId+'|'+id+'|'+field);if(draft)e[field]=draft.value;}const prev=previousEntry(r,id)||{actual:0};if(k==='weekly'){const act=+(Number(prev.actual||0)+Number(input.value||0)).toFixed(2);e.actual=act;const actInput=tr.querySelector('[data-entry="actual"]');if(actInput&&document.activeElement!==actInput)actInput.value=act;editDrafts.set(reportId+'|'+id+'|actual',{reportId,id,k:'actual',value:act});}else if(k==='actual'){const w=+(Number(input.value||0)-Number(prev.actual||0)).toFixed(2);e.weekly=w;const wInput=tr.querySelector('[data-entry="weekly"]');if(wInput&&document.activeElement!==wInput)wInput.value=w;editDrafts.set(reportId+'|'+id+'|weekly',{reportId,id,k:'weekly',value:w});}applyWeeklyAutoRules(e,k,rawVal,r,prev);const paySelect=tr.querySelector('[data-entry="payment"]');if(paySelect&&paySelect.value!==e.payment){paySelect.value=e.payment;editDrafts.set(reportId+'|'+id+'|payment',{reportId,id,k:'payment',value:e.payment});}const noteInput=tr.querySelector('[data-entry="note"]');if(noteInput&&document.activeElement!==noteInput&&noteInput.value!==(e.note||'')){noteInput.value=e.note||'';editDrafts.set(reportId+'|'+id+'|note',{reportId,id,k:'note',value:e.note||''});}const st=statusKey(e);tr.className=st==='paid'?'paid':st==='deliver'?'waiting-delivery':st==='pay'?'waiting-payment':'';persistEdits();updateSaveStatus();};input.onchange=()=>{const isBatch=localStorage.getItem('pn-weekly-batch-mode')==='true',val=input.type==='checkbox'?input.checked:['plan','weekly','actual'].includes(k)?+input.value:input.value;if(isBatch)input.oninput?.();else submitWeeklyEdit(reportId,id,k,val);};});}
function bindListSearches(){
 for(const id of ['search','registry-search','archive-search','p301-search','audit-search']){const input=document.getElementById(id);if(!input)continue;
 const run=async()=>{const token=++searchGeneration;if(!input.isConnected)return;if(id==='audit-search'){auditQuery=input.value;await loadHistoryPage(1);if(token!==searchGeneration||!input.isConnected)return;}else if(id==='archive-search'){archiveQuery=input.value;archivePage=1;}else if(id==='p301-search'){p301Query=input.value;page=1;}else{query=input.value;page=1;}refreshListResults(id);};
 const schedule=e=>{if(e.isComposing)return;clearTimeout(listSearchTimer);clearTimeout(searchTimer);if(!input.value){void run().catch(e=>toast(e.message,true));return;}listSearchTimer=setTimeout(()=>void run().catch(e=>toast(e.message,true)),id==='audit-search'?300:120);};input.oninput=schedule;input.oncompositionend=schedule;
 }
}
