 const focused=document.getElementById(id),caret=focused?.selectionStart,end=focused?.selectionEnd;
 if(view==='dashboard'){const markup=document.createElement('template');markup.innerHTML=dashboard();const current=$('#app .dashboard-shell'),fresh=markup.content.querySelector('.dashboard-shell');if(current&&fresh){const retainedSearch=current.querySelector('#search'),freshSearch=fresh.querySelector('#search');if(retainedSearch&&freshSearch)freshSearch.replaceWith(retainedSearch.closest('.search-field')||retainedSearch);current.replaceWith(fresh);bind();bindReferenceDashboardControls();mountSelections();mountTablePresentation();bindListSearches();if(focused?.isConnected){focused.focus({preventScroll:true});focused.setSelectionRange(caret,end);}scheduleOperationalLayout();}return;}
 const template=document.createElement('template');template.innerHTML=id==='audit-search'?audit():view==='projects'?registryTable():view==='reports'?reports():view==='p301'?p301():projectTable(activeRows(),view==='weekly',view==='dashboard');
