function workBudgetDialog(code){const node=workCodePath(code).node,links=workCodeBudgetLinks(state).filter(l=>l.code===code),registered=new Set(links.filter(l=>l.source==='registry').map(l=>l.budgetAccountId));modal('ผูกบัญชีงบประมาณ · '+code,`<form id="work-budget-form"><p>${esc(node.name)}</p><p class="hint">ความสัมพันธ์จากทะเบียนสัญญายังคงอยู่ เลือกเพิ่มบัญชีที่ใช้กับรหัสงานนี้ได้</p><div class="form-grid">${state.budgetAccounts.map(b=>`<label class="field"><span><input type="checkbox" name="budgetIds" value="${esc(b.id)}" ${links.some(l=>l.budgetAccountId===b.id)?'checked':''} ${registered.has(b.id)?'disabled':''}> ${esc(b.name)}${registered.has(b.id)?' · จากทะเบียนสัญญา':''}</span></label>`).join('')}</div><div class="actions"><button type="button" class="btn" id="work-budget-back">กลับ</button><button class="btn primary" type="submit">บันทึกความสัมพันธ์</button></div></form>`,f=>withButtonLock($('#work-budget-form [type=submit]'),()=>mutate('ผูกบัญชีงบประมาณกับรหัสงาน '+code,s=>{const next=applyWorkCodeCatalog(s),path=workCodePath(code),ids=new Set([...f.getAll('budgetIds'),...registered]);next.settings.workCodeBudgetLinks=workCodeBudgetLinks(next).filter(l=>l.code!==code||l.source==='registry');for(const id of ids)if(!next.settings.workCodeBudgetLinks.some(l=>l.code===code&&l.budgetAccountId===id))next.settings.workCodeBudgetLinks.push({code,budgetAccountId:id,projectId:path.project?.id||'',activityId:path.activity?.id||'',source:'manual'});s.workCodes=next.workCodes;s.workNames=next.workNames;s.settings=next.settings;})));$('#work-budget-back').onclick=workCatalogDialog;}
