/** Render catalog from the current validated scope. @returns {string} HTML; does not save business records. */
function catalog(){return header('ข้อมูลพื้นฐาน','')+catalogManager.html();}
function bindCatalog(){catalogManager.bind();$('#depreciation-reference')?.addEventListener('click',()=>depreciationCatalogDialog());$('#work-catalog-reference')?.addEventListener('click',workCatalogDialog);}
async function loadWorkspace(scope){
 const data=await cloud.loadCloud({...scope||{funding,year},screen:true});if(!data)return data;
 const jobs=[];
 if(data.referenceDeferred)jobs.push((async()=>{let cached;try{cached=JSON.parse(localStorage.getItem('pn-weekly-branding')||'null');}catch{}const branding=await cloud.loadBrandingCloud(cached?.hash),asset=branding?.notModified?cached:branding;if(asset&&typeof asset.logo==='string'){data.settings.logo=asset.logo;try{localStorage.setItem('pn-weekly-branding',JSON.stringify(asset));}catch{}}})());
 const r=data.loadedScope&&data.reports.find(r=>r.id===data.loadedScope.reportId);
 if(r?.locked&&Object.keys(r.entries||{}).length&&!Object.keys(r.snapshots||{}).length)jobs.push((async()=>{const detail=await cloud.loadDetailCloud(r.id);if(!detail?.report||detail.revision!==data.revision)throw Error('ข้อมูลเปลี่ยนระหว่างโหลดรายงาน กรุณาโหลดล่าสุดอีกครั้ง');data.reports=data.reports.map(x=>x.id===r.id?detail.report:x);data.loadedScope={...data.loadedScope,previousEntries:detail.previousEntries||data.loadedScope.previousEntries||{}};})());
 const results=await Promise.allSettled(jobs);const failed=results.find(result=>result.status==='rejected');if(failed)throw failed.reason;
 data.importHistoryDeferred=true;if(!data.contractors){normalizeState(data);const result=await cloud.saveCloud(data,data.revision||0);data.revision=result.revision;}return data;
}

function weekLabel(r){if(/^สัปดาห์ที่/.test(r.title))return r.title;const n=r.title.match(/(?:รอบที่|สัปดาห์ที่)\s*(\d+)/);return 'สัปดาห์ที่ '+(n?.[1]||state.reports.filter(x=>(!x.year||x.year===year)&&(!x.funding||x.funding===funding)).slice().sort((a,b)=>(a.end||'').localeCompare(b.end||'')).findIndex(x=>x.id===r.id)+1);}
function applyBrand(){document.title=state.settings.systemName;$('#system-name').textContent=state.settings.systemName;const logo=$('.brand .logo');logo.classList.toggle('uploaded-logo',!!state.settings.logo);logo.innerHTML=state.settings.logo?'<img alt="โลโก้" src="'+state.settings.logo+'">':'P<span>n</span>';let icon=document.querySelector('link[rel=icon]');if(!icon){icon=document.createElement('link');icon.rel='icon';document.head.append(icon);}icon.href=state.settings.logo||'data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="12" fill="#145744"/><text x="13" y="44" font-size="36" fill="white">P</text></svg>');document.querySelector('footer').textContent=state.settings.systemName;}
function readPNG(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas');const scale=Math.min(1,256/img.width,256/img.height);c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/png'));};img.onerror=()=>reject(Error('อ่านภาพ PNG ไม่สำเร็จ'));img.src=reader.result;};reader.onerror=()=>reject(Error('อ่านไฟล์ไม่ได้'));reader.readAsDataURL(file);});}
function amendDialog(pid){const r=report(),rows=activeRows();if(!rows.length)return toast('ไม่มีรายการให้แก้ไข',true);pid||=rows[0].p.id;const e=entryFor(r,pid),prev=previousEntry(r,pid)||{actual:0};modal('แก้ไขรายงานย้อนหลัง · '+weekLabel(r),`<form id="amend-form"><div class="notice">แก้ข้อมูลแล้วกดบันทึกได้ทันที ประวัติจะเก็บให้อัตโนมัติ</div>${selectField('สัญญาที่ต้องการแก้ไข','contractId',rows.map(x=>({value:x.p.id,label:x.p.contract+' · '+x.p.title})),pid)}<div class="form-grid">${field('แผนงานสะสม (%)','plan',e.plan,'number','min="0" max="100" step="0.01" required')}${field('ผลงานรายสัปดาห์ (%)','weekly',e.weekly,'number','min="0" max="100" step="0.01" required')}${field('ผลงานสะสม (%)','actual',e.actual,'number','min="0" max="100" step="0.01" required')}${selectField('สถานะเบิกจ่าย','payment',['รอส่งมอบงาน','รอเบิกจ่าย','เบิกจ่ายแล้ว'],e.payment)}${field('วันที่ส่งมอบงาน','deliveryDate',e.deliveryDate||'','date')}${field('วันที่ตรวจรับงาน','acceptanceDate',e.acceptanceDate||'','date')}${field('วันที่เบิกจ่าย','paymentDate',e.paymentDate||parsePaymentDate(e.note),'date')}${field('หมายเหตุ','note',e.note,'textarea')}</div><p class="form-error" role="alert"></p>${buttons('บันทึกการแก้ไข')}</form>`,async f=>{const patch={};for(const k of ['plan','weekly','actual','note','payment','paymentDate','deliveryDate','acceptanceDate']){const v=['plan','weekly','actual'].includes(k)?+f.get(k):String(f.get(k)||'');const original=k==='paymentDate'?e.paymentDate||parsePaymentDate(e.note):e[k]??'';if(v!==original)patch[k]=v;}
 if(!Object.keys(patch).length)throw Error('ยังไม่มีข้อมูลเปลี่ยนแปลง');await saveAmendment(r.id,{[pid]:patch});});const form=$('#amend-form');form.addEventListener('input',ev=>{if(ev.target!==form.elements.contractId)form.elements.contractId.disabled=true;});form.elements.contractId.value=pid;form.elements.contractId.onchange=()=>amendDialog(form.elements.contractId.value);form.elements.payment.value=e.payment;
 form.elements.weekly.oninput=()=>{form.elements.actual.value=+(Number(prev.actual)+Number(form.elements.weekly.value)).toFixed(2);};form.elements.actual.oninput=()=>{form.elements.weekly.value=+(Number(form.elements.actual.value)-Number(prev.actual)).toFixed(2);};form.elements.payment.onchange=()=>{if(form.elements.payment.value==='เบิกจ่ายแล้ว'&&!form.elements.paymentDate.value)form.elements.paymentDate.value=r.reference||today();updateNote();};const updateNote=()=>{if(form.elements.payment.value==='เบิกจ่ายแล้ว'&&form.elements.paymentDate.value)form.elements.note.value=paymentNote({payment:'เบิกจ่ายแล้ว',paymentDate:form.elements.paymentDate.value});};form.elements.paymentDate.onchange=updateNote;
}
function showFormError(form,message,input){const info=saveFailureInfo(message);operationFeedback('error',{problem:message instanceof Error?message:Error(String(message))});let el=(form.id==='contract-form'?$('#modal .dialog-footer > .form-error'):null)||form.querySelector(':scope > .form-error');if(!el){el=document.createElement('p');el.className='form-error';el.setAttribute('role','alert');form.append(el);}el.id='active-form-error';el.textContent=info.reason+' · วิธีแก้: '+info.fix;const target=input||(info.field&&form.elements?.namedItem(info.field))||form.querySelector('input:not([type=hidden]),select,textarea');target?.setAttribute('aria-describedby',el.id);if(input||info.field)target?.setAttribute('aria-invalid','true');target?.focus();target?.scrollIntoView({block:'nearest'});}
function saveAmendment(id,patch,options){return enqueueSave(()=>runAmendment(id,patch,options));}
async function runAmendment(id,patch,options){const refresh=()=>{if(options?.inlineId&&view==='weekly'&&selected===id)updateWeeklyRowDOM(options.inlineId);else render();};busy=true;try{if(!navigator.onLine||!cloudMode||outbox.some(j=>j.kind!=='activity')){const before=state,next=amendReport(state,id,patch),delta=workspaceChanges(before,next);await saveLocalJob(before,next,delta,'แก้ไขรายงานย้อนหลัง',undefined,undefined,'amendment',{reportId:id,patch});state=next;activeRowsCache=undefined;refresh();toast('บันทึกการแก้ไขบนเครื่องแล้ว — รอส่ง');return;}if(!cloudMode&&cloud.config())throw Error('ยังไม่เชื่อมต่อฐานข้อมูล กรุณาโหลดข้อมูลล่าสุดก่อนบันทึก');let next;if(cloudMode){const result=await cloud.amendCloud(id,patch,state.revision||0);next=result.document||{...state,revision:result.revision,reports:state.reports.map(r=>{const changed=result.reports.find(x=>x.id===r.id);return changed?{...r,...changed.metadata,entries:{...r.entries,...changed.entries}}:r;}),contractRegistry:state.contractRegistry.map(r=>result.registry.find(x=>x.id===r.id)||r),amendments:[result.amendment,...(state.amendments||[])].slice(0,100),audit:[result.auditEntry,...state.audit].slice(0,2000)};}else{next=amendReport(state,id,patch);next.revision=(state.revision||0)+1;}normalizeState(next);try{await cacheWorkspace(next);}catch(e){if(!cloudMode)throw e;toast('บันทึกบน Supabase แล้ว แต่สำรองบนอุปกรณ์ไม่สำเร็จ',true);}state=next;activeRowsCache=undefined;refresh();toast('บันทึกการแก้ไขย้อนหลังแล้ว');}finally{busy=false;}}
